package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Explicit user teaching and external evidence, retrieved as attributed text; never executable instructions. */
final class KnowledgeNotebook{
 static final int MAX=128,TEXT=262144,BUDGET=4000000;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-knowledge-notebook",0);}
 static JSONArray data(Context c)throws Exception{return NotebookDisk.of(c).legacyRows();}
 static void validate(JSONArray rows)throws Exception{if(rows.length()>MAX||rows.toString().length()>BUDGET)throw new IllegalArgumentException("Cuaderno demasiado grande");Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);RuntimeProgram.keys(r,"id","title","text","source","origin","saved","truncated");if(!r.getString("id").matches("[a-f0-9]{64}")||!ids.add(r.getString("id"))||r.getString("title").length()>160||r.getString("text").trim().isEmpty()||r.getString("text").length()>TEXT||r.getString("source").length()>2000||!r.getString("origin").matches("user|web")||r.getLong("saved")<0)throw new IllegalArgumentException("Entrada inválida");r.getBoolean("truncated");if(r.getString("origin").equals("web")&&!r.getString("source").startsWith("https://"))throw new IllegalArgumentException("Fuente web sin HTTPS");}}
 static JSONObject entry(String title,String text,String source,String origin,long time)throws Exception{if(text.trim().isEmpty())throw new IllegalArgumentException("No recibí contenido para guardar");boolean clipped=text.length()>TEXT;String limited=text.substring(0,Math.min(text.length(),TEXT));String heading=title.trim();if(heading.isEmpty())heading=limited.substring(0,Math.min(80,limited.length()));heading=heading.substring(0,Math.min(160,heading.length()));String id=JavaMethodEditor.hash(origin+"|"+(origin.equals("web")?source:limited));return new JSONObject().put("id",id).put("title",heading).put("text",limited).put("source",source).put("origin",origin).put("saved",time).put("truncated",clipped);}
 static JSONArray merge(JSONArray old,JSONObject item)throws Exception{JSONArray next=new JSONArray();next.put(item);for(int i=0;i<old.length();i++)if(!old.getJSONObject(i).getString("id").equals(item.getString("id")))next.put(old.getJSONObject(i));validate(next);return next;}
 static String remember(Context c,String title,String text,String source,String origin)throws Exception{return rememberReader(c,title,new StringReader(text),source,origin);}
 static String rememberReader(Context c,String title,Reader text,String source,String origin)throws Exception{String saved=NotebookDisk.of(c).put(title,text,source,origin);try{return saved+"\n"+ReadingTraining.afterLearning(c);}catch(Exception e){return saved+"\nDocumento conservado; entrenamiento pendiente: "+AndroidRepair.summary(e);}}
 static void restore(Context c,JSONArray rows)throws Exception{NotebookDisk.of(c).restoreLegacy(rows);}
 static String[] chunks(String text){List<String> out=new ArrayList<>();for(String part:text.split("(?<=[.!?])\\s+|[\\r\\n]+")){String p=part.trim();while(p.length()>700){int end=p.lastIndexOf(' ',700);if(end<150)end=700;out.add(p.substring(0,end));p=p.substring(end).trim();}if(!p.isEmpty())out.add(p);}return out.toArray(new String[0]);}
 static String retrieve(JSONArray rows,String query)throws Exception{return ReadingKnowledge.answer(rows,query);}
 static String reply(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);if(!ReadingKnowledge.informative(input))return null;JSONArray rows=NotebookDisk.of(c).selected(input);String result=retrieve(rows,input);if(result==null)result=ReadingKnowledge.missing(rows,input);if(result!=null)result=ReadingKnowledge.style(result,MobileCore.prefs(c).getString("style","normal"),rows,input);if(result==null&&q.matches("(?s).*(?:pagina|enlace|lo que aprendiste|lo que guardaste).*"))return "No encontré un fragmento suficientemente relacionado en el cuaderno. Decime el tema de la fuente o pasame el enlace.";return result;}
 static final class Intent{String kind="",text="",url="";boolean crawl;Intent(String k,String t){kind=k;text=t;}}
 static boolean teachingMessage(String text){if(text.length()>TEXT+64)return false;try{Intent p=parse(text);return p!=null&&p.kind.equals("teach")&&p.text.length()<=TEXT;}catch(Exception e){return false;}}
 static Intent parse(String raw){String clean=NaturalCoding.polite(raw).trim(),q=ChatLanguage.normalize(clean);String crawling=PageCrawl.preference(clean);if(crawling!=null)return new Intent("crawl_"+crawling,"");if(q.startsWith("no "))return null;if(PageCrawl.followUp(clean))return new Intent("crawl_last",clean);if(q.startsWith("recorda que ")||q.startsWith("recuerda que "))return null;if(q.startsWith("aprende esta respuesta")||q.startsWith("aprende esta variante"))return null;
  if(q.matches("aprende de un archivo|lee un archivo|importa un texto|importa un archivo de texto|aprende un archivo de texto"))return new Intent("file","");
  if(q.matches("respalda mi conocimiento|respalda mis conocimientos|exporta mis conocimientos|exporta mi conocimiento|respalda mi memoria|guarda un respaldo del conocimiento|guarda todo lo que aprendiste"))return new Intent("export","");
  if(q.matches("restaura mis conocimientos|importa mis conocimientos|recupera mi memoria|restaura mi conocimiento"))return new Intent("import","");
  if(q.matches("que palabras aprendiste|mi vocabulario|tu vocabulario aprendido|que vocabulario aprendiste|mostrame tu vocabulario"))return new Intent("vocabulary","");
  if(q.matches("resumilo|resumelo|resumi la pagina|que dice ese enlace|que aprendiste de ese enlace|que recordas de esa pagina"))return new Intent("last","");if(q.matches("que aprendiste|que conocimientos guardaste|mostrame lo que aprendiste|mis conocimientos|que sabes de lo que te ensene"))return new Intent("status","");if(q.matches("borra todos los conocimientos guardados|olvida todos los conocimientos guardados"))return new Intent("clear","");if(q.matches("(?:hacete|hazte|volvete|vuelvete) mas inteligente|mejora tu inteligencia"))return new Intent("coach","");
  String link=PageLinks.extract(clean);if(link!=null){Intent intent=new Intent("web",clean);intent.url=link;intent.crawl=PageCrawl.wanted(clean);return intent;}
  Matcher topic=Pattern.compile("(?isu)^(?:aprende|aprendé|aprendas|aprender) (?:sobre|acerca de) (.{2,100})[.! ]*$").matcher(clean);if(topic.matches())return new Intent("topic",topic.group(1).trim());
  Matcher teach=Pattern.compile("(?isu)^(?:aprende|aprendé|aprendas)(?: (?:que|esto|lo siguiente))?\\s*[: ]\\s*(.+)$|^(?:recorda|recordá|recuerda|recuerdes|guarda|guardá|guardes) (?:que|esto|lo siguiente)\\s*[: ]?\\s*(.+)$").matcher(clean);if(teach.matches()){String content=teach.group(1)!=null?teach.group(1).trim():teach.group(2).trim();String normalized=ChatLanguage.normalize(content);if(normalized.matches("esto|eso|lo siguiente|lo anterior"))throw new IllegalArgumentException("Pasame el contenido o el enlace que querés que aprenda; no guardé una palabra sin información.");if(q.startsWith("aprende ")&&!q.startsWith("aprende que ")&&!q.startsWith("aprende esto")&&!clean.contains(":")&&normalized.split(" ").length<=5&&!normalized.matches("(?s).*\\b(?:es|son|tiene|usa|llama|significa)\\b.*"))return new Intent("topic",content);return new Intent("teach",content);}return null;
 }
 static String crawl(final Context c,Intent p,PageLoader pages)throws Exception{PageCrawl.Plan plan=PageCrawl.plan(p.text,p.url);PageCrawl.Report report=PageCrawl.run(plan,pages,new PageCrawl.Saver(){public String save(PageReader.Document d)throws Exception{return rememberReader(c,d.title,d.reader(),d.url,"web");}});return PageCrawl.describe(plan,report);}
 interface PageLoader{PageReader.Document load(String url)throws Exception;}
 static final PageLoader PAGES=new PageLoader(){public PageReader.Document load(String url)throws Exception{return PageReader.fetch(url);}};
 static BananaEngine.Result handle(final Context c,String input)throws Exception{return handle(c,input,new PageLoader(){public PageReader.Document load(String url)throws Exception{return PageReader.fetch(c,url);}});}
 static BananaEngine.Result handle(Context c,String input,PageLoader pages)throws Exception{Intent p;try{p=parse(input);}catch(IllegalArgumentException e){return MobileCore.say(c,e.getMessage(),"aprendizaje_local");}if(p==null)return null;JavaChat.owner=Thread.currentThread();try{String text;if(p.kind.equals("file"))return MobileCore.say(c,"Elegí un archivo TXT o Markdown UTF-8. Lo guardaré por fragmentos sin cargarlo completo en el chat.","knowledge_import_text");else if(p.kind.equals("export")){NotebookArchive.export(c);return MobileCore.say(c,"Preparé un respaldo completo de los documentos y su índice de fuentes para guardarlo.","knowledge_export");}else if(p.kind.equals("import"))return MobileCore.say(c,"Elegí el respaldo ZIP de conocimiento. Validaré sus documentos antes de incorporarlos; conservaré las fuentes privadas con el mismo identificador.","knowledge_import");else if(p.kind.equals("vocabulary"))text=NotebookDisk.of(c).vocabulary();else if(p.kind.equals("status"))text=NotebookDisk.of(c).summary();else if(p.kind.equals("last")){JSONArray rows=NotebookDisk.of(c).latest();if(rows.length()==0)text="Todavía no hay una fuente reciente en esta biblioteca.";else{JSONObject row=rows.getJSONObject(0);StringBuilder excerpts=new StringBuilder("Fragmentos iniciales de la última fuente guardada:\n");String[] parts=chunks(row.getString("text"));for(int i=0;i<Math.min(3,parts.length);i++)excerpts.append(parts[i]).append("\n");text=excerpts+"Fuente: "+row.getString("source")+". Es extracción, no verificación externa.";}}else if(p.kind.equals("clear")){NotebookDisk.of(c).clear();try{ReadingTraining.forgot(c);LearningLoop.forget(c);text="Borré documentos, ejercicios y cola de entrenamiento. Los pesos ya entrenados se conservan; borrar texto no desentrena el modelo.";}catch(Exception cleanup){text="Borré los documentos; faltó limpiar parte del progreso o los ejercicios: "+AndroidRepair.summary(cleanup);}}else if(p.kind.equals("crawl_on")){PageCrawl.prefs(c).edit().putBoolean("always",true).commit();text="Desde ahora, cuando me pases un enlace también leo sus subenlaces del mismo sitio: "+PageCrawl.DEFAULT_DEPTH+" niveles y hasta "+PageCrawl.DEFAULT_PAGES+" páginas por recorrido, salvo que indiques otros números. Para volver a una sola página decí «no leas los subenlaces».";}else if(p.kind.equals("crawl_off")){PageCrawl.prefs(c).edit().putBoolean("always",false).commit();text="Listo: leo sólo la página que me pases. Para un recorrido puntual decí «leé los subenlaces» junto al enlace.";}else if(p.kind.equals("crawl_last")){JSONArray rows=NotebookDisk.of(c).latest();if(rows.length()==0||!rows.getJSONObject(0).optString("origin").equals("web"))text="No tengo una página web reciente de la cual seguir enlaces. Pasame el enlace junto con «leé los subenlaces».";else{p.url=rows.getJSONObject(0).getString("source");p.kind="web";text=crawl(c,p,pages);}}else if(p.kind.equals("coach"))text="Puedo aprender contenido que me enseñes y retener páginas públicas. Decime qué tema querés que aprenda o pasame el texto/enlace. También puedo entrenar el Transformer si me pedís mejorar Chat más a fondo, pero pocos ejemplos no garantizan inteligencia general. No cambié pesos ni código con este pedido impreciso.";else if(p.kind.equals("teach"))text=remember(c,"",p.text,"user","user");else if(p.kind.equals("topic")){JavaChat.phase("Consultando una fuente sobre "+p.text+"…");String topic=Knowledge.normalize(p.text);WebMemory.lookup(c,topic);JSONObject row=WebMemory.forTopic(c,topic);if(row==null)throw new IOException("No encontré una fuente que pudiera guardar");text=remember(c,row.getString("title"),row.getString("text"),row.getString("source"),"web");}else{JavaChat.phase("Leyendo la página pública y guardando su texto…");if(p.crawl||PageCrawl.always(c))text=crawl(c,p,pages);else try(PageReader.Document d=pages.load(p.url)){text=rememberReader(c,d.title,d.reader(),d.url,"web");int more=PageCrawl.sameSite(d);if(more>0)text+="\nEsta página enlaza "+more+(more==1?" subenlace":" subenlaces")+" del mismo sitio. Si querés que también los lea, decí «leé los subenlaces».";}}return MobileCore.say(c,text,"aprendizaje_local");}catch(Exception e){return MobileCore.say(c,p.kind.equals("web")?PageReader.failure(p.url,e):"No pude incorporar conocimiento nuevo: "+AndroidRepair.summary(e),"aprendizaje_local");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
